//! Required Select required boolean reflection retains actual attributes.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><select id=select required=legacy><option id=option value=one>One</option><option value=two>Two</option></select><datalist id=choices><option id=suggestion>Suggestion</option></datalist><input id=neighbor value=seed></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://select-required.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}

#[test]
fn select_required_canonical_boolean_accessor_and_actual_presence(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('select'),P=HTMLSelectElement.prototype,a=Object.getOwnPropertyDescriptor(P,'required');if(!a||!a.enumerable||!a.configurable||a.get.length!==0||a.set.length!==1||a.get.name!=='get required'||a.set.name!=='set required'||Object.hasOwn(x,'required')||x.required!==true||x.getAttribute('required')!=='legacy'||document.createElement('select').required!==false)throw 'canonical disabled boolean';"#);}
#[test]
fn select_required_native_boolean_conversion_identity_and_observer_old_values(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('select'),old=x.getAttributeNode('required'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});x.required=false;var records=watch.takeRecords();if(x.required!==false||old.ownerElement!==null||old.value!=='legacy'||records.length!==1||records[0].oldValue!=='legacy'||records[0].attributeName!=='required')throw 'false removes actual attribute';var calls=0;x.required={toString:function(){calls++;return '';},valueOf:function(){calls++;return 0;}};var attr=x.getAttributeNode('required');records=watch.takeRecords();if(calls||x.required!==true||attr===null||attr.value!==''||records.length!==1||records[0].oldValue!==null||document.getElementById('neighbor').value!=='seed')throw 'boolean conversion keeps actual record';x.required='';if(x.required!==false||attr.ownerElement!==null)throw 'empty string is false';"#);}
#[test]
fn select_required_inert_exact_namespace_and_independent_copies(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var doc=new Document(),x=doc.createElementNS('http://www.w3.org/1999/xhtml','t:select');if(!(x instanceof HTMLSelectElement)||x.required!==false)throw 'inert absent disabled';x.setAttributeNS('urn:foreign','required','foreign');x.setAttributeNS(null,'REQUIRED','upper');if(x.required!==false)throw 'exact disabled namespace and case';x.required=true;var attr=x.getAttributeNodeNS(null,'required');if(x.required!==true||attr===null||attr.value!=='')throw 'inert actual boolean';x.removeAttributeNS('urn:foreign','required');x.removeAttributeNS(null,'REQUIRED');var clone=x.cloneNode(false),copy=x.cloneNode(false);if(!(clone instanceof HTMLSelectElement)||!(copy instanceof HTMLSelectElement)||clone.required!==true||copy.required!==true||copy.ownerDocument!==doc||clone.getAttributeNode('required')===attr)throw 'independent boolean copies';clone.required=false;if(x.required!==true||copy.required!==true||clone.required!==false)throw 'independent disabled removal';var caught=false;try{doc.importNode(x,false);}catch(e){caught=e instanceof DOMException&&e.name==='NotSupportedError';}if(!caught||x.required!==true||copy.required!==true||clone.required!==false||attr.ownerElement!==x||x.ownerDocument!==doc)throw 'inert option import lifecycle guard';"#);}

#[test]
fn select_required_truthiness_does_not_invoke_author_conversion(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('select'),a=Object.getOwnPropertyDescriptor(HTMLSelectElement.prototype,'required'),calls=0,author={toString:function(){calls++;throw 'conversion';},valueOf:function(){calls++;throw 'conversion';}};for(var value of [false,0,-0,NaN,'',null,undefined,BigInt(0)]){a.set.call(x,value);if(x.required!==false||x.hasAttribute('required'))throw 'false boolean value';}for(var value of [true,1,-1,Infinity,'false',[],{},new Boolean(false),Symbol('boolean'),BigInt(1),author]){a.set.call(x,value);if(x.required!==true||x.getAttribute('required')!==''||calls)throw 'true boolean value';}a.set.call(x);if(x.required!==false||calls)throw 'missing boolean argument';"#);}



#[test]
fn select_required_brand_precedes_hooks_and_keeps_author_override(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('select'),C=HTMLSelectElement,P=C.prototype,a=Object.getOwnPropertyDescriptor(P,'required'),calls=0;for(var bad of [{},Object.create(P),document.body,document.createElement('p'),document.createElement('ul'),document.createElement('li'),document.createElement('dl'),document.getElementById('neighbor'),document.createElementNS('urn:foreign','select'),new Document().createElementNS('http://www.w3.org/1999/xhtml','OL')]){var caught=false;try{a.get.call(bad);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'disabled getter concrete brand';caught=false;try{a.set.call(bad,{toString:function(){calls++;return '';}});}catch(e){caught=e instanceof TypeError;}if(!caught||calls)throw 'disabled setter brand';}Object.defineProperty(x,'required',{value:'author',writable:true,configurable:true});a.set.call(x,false);if(x.required!=='author'||x.hasAttribute('required'))throw 'canonical attribute authority';delete x.required;if(x.required!==false||Object.hasOwn(x,'required'))throw 'restored inherited boolean';delete window.HTMLSelectElement;if(!(x instanceof C)||Object.getPrototypeOf(x)!==P)throw 'saved canonical interface';"#);}
#[test]
fn select_required_raw_attribute_aliases_observe_presence_and_preserve_exact_backing(){let(mut d,mut f,mut p)=fixture();for inert in [false,true]{run(&mut d,&mut f,&mut p,if inert{"var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','select');x.required=true;"}else{"var x=document.getElementById('select');"});run(&mut d,&mut f,&mut p,r#"var a=x.getAttributeNode('required'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});for(var key of ['value','nodeValue','textContent']){a[key]='R\ud800'+key;if(x.required!==true||a.value!=='R\ud800'+key||x.getAttributeNode('required')!==a)throw 'raw boolean backing';}var old=a.value;x.required=true;var records=watch.takeRecords();if(x.required!==true||a.value!==''||records.length!==4||records[3].oldValue!==old||x.getAttributeNode('required')!==a)throw 'boolean normalization uses current Attr';x.removeAttribute('required');if(x.required!==false||a.ownerElement!==null)throw 'actual boolean removal';x.setAttributeNS('urn:foreign','required','foreign');x.setAttributeNS(null,'REQUIRED','upper');if(x.required!==false)throw 'exact disabled authority';x.setAttributeNS(null,'required','A\udfffZ');if(x.ownerDocument!==document){var clone=x.cloneNode(false);if(!x.required||!clone.required||clone.getAttributeNodeNS(null,'required').value!=='A\udfffZ'||clone.getAttributeNodeNS(null,'required')===x.getAttributeNodeNS(null,'required'))throw 'raw presence copy';}"#);}}
#[test]
fn select_required_saved_child_origin_refuses_before_observation_and_recovers(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('select'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var a=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLSelectElement.prototype,'required');a.set.call(x,false);if(a.get.call(x)!==false)throw 'same origin boolean';");p.set_location(&crate::navigation::address("https://other-disabled.test/",&crate::navigation::Location::home()).unwrap());let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;for source in ["a.get.call(x);","a.set.call(x,true);"]{p.begin_job();let e=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);}p.set_location(&crate::navigation::address("https://select-required.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(x.required!==false)throw 'origin refusal preserves value';a.set.call(x,true);if(!a.get.call(x)||x.getAttribute('required')!=='')throw 'saved boolean recovery';");}

#[test]
fn select_required_writer_resource_refusal_is_atomic_and_recovers(){for inert in [false,true]{for mode in 0..4{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','select');"}else{"var x=document.getElementById('select');x.required=false;"});run(&mut d,&mut f,&mut p,"var watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone());let limit=p.state.retained_limit;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,_=>p.state.execution_deadline=Some(Instant::now())};let e=p.runtime.execute("x.required=true;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("work")||e.contains("allowance")||e.contains("limit")||e.contains("bound"),"{inert}/{mode}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone()),state);p.state.retained_limit=limit;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"if(x.required!==false||watch.takeRecords().length)throw 'atomic disabled refusal';x.required=true;var records=watch.takeRecords();if(x.required!==true||x.getAttribute('required')!==''||records.length!==1||records[0].oldValue!==null)throw 'fresh boolean recovery';");}}}
#[test]
fn select_required_reads_charge_names_work_and_deadline_without_string_copy_or_retained_growth(){for inert in [false,true]{for mode in 0..3{let(mut d,mut f,mut p)=fixture();let object=if inert{let Value::Host(object)=p.runtime.execute("var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','select');x.required=true;x;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("inert SELECT")};object}else{node_handle((0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("select")).unwrap())};let before=format!("{:?}",d.nodes);let retained=p.state.retained;let limit=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.execution_deadline=Some(Instant::now()),_=>{p.state.retained_limit=retained;p.state.copy_work=0;p.state.limits.host.string_bytes=0;}}let result=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.select_required_get(object);if mode==2{assert!(matches!(result,Ok(Value::Bool(true))));}else{assert!(result.is_err());}assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.retained,retained);p.state.retained_limit=limit;p.state.limits.host.string_bytes=strings;p.state.execution_deadline=None;p.begin_job();assert!(matches!(Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.select_required_get(object),Ok(Value::Bool(true))));}}}


fn validation_fixture()->(Document,Forms,Page,usize,usize){let mut d=crate::html::parse("<form id=form><select id=select name=pick><option value=''>Choose</option><option disabled value=one>One</option><optgroup label=Other><option value=''>Empty valid choice</option></optgroup></select><input id=neighbor value=seed></form>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);let owner=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("form")).unwrap();let select=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("select")).unwrap();(d,f,p,owner,select)}
#[test]
fn select_required_drives_actual_native_placeholder_validation_without_selection_or_events(){let(mut d,mut f,mut p,owner,select)=validation_fixture();let state=format!("{:?}",f.controls[&select].select);assert!(f.validate_submission(&d,owner,None).is_ok());run(&mut d,&mut f,&mut p,"var x=document.getElementById('select'),events=0;x.addEventListener('input',function(){events++;});x.addEventListener('change',function(){events++;});x.required=true;if(!x.required||x.value!==''||x.selectedIndex!==0||events)throw 'required preserves current placeholder';");assert!(f.controls[&select].required);assert_eq!(format!("{:?}",f.controls[&select].select),state);assert!(f.validate_submission(&d,owner,None).unwrap_err().contains("required"));run(&mut d,&mut f,&mut p,"x.required=false;if(events)throw 'no fabricated events';");assert!(!f.controls[&select].required);assert!(f.validate_submission(&d,owner,None).is_ok());}
#[test]
fn select_required_disabled_bypass_scripted_choices_and_reset_retain_actual_defaults(){let(mut d,mut f,mut p,owner,select)=validation_fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('select');x.required=true;x.disabled=true;");assert!(f.validate_submission(&d,owner,None).is_ok());run(&mut d,&mut f,&mut p,"x.disabled=false;x.selectedIndex=1;");assert!(f.validate_submission(&d,owner,None).is_ok());run(&mut d,&mut f,&mut p,"x.selectedIndex=-1;");assert!(f.validate_submission(&d,owner,None).is_err());run(&mut d,&mut f,&mut p,"x.selectedIndex=2;");assert!(f.validate_submission(&d,owner,None).is_ok());f.reset_in_document(&d,owner).unwrap();assert!(f.controls[&select].required);assert_eq!(f.controls[&select].select.as_ref().unwrap().selected,Some(0));assert!(f.validate_submission(&d,owner,None).is_err());run(&mut d,&mut f,&mut p,"if(!x.required||x.selectedIndex!==0)throw 'reset keeps current required attribute';x.required=false;");f.reset_in_document(&d,owner).unwrap();assert!(f.validate_submission(&d,owner,None).is_ok());}
#[test]
fn select_required_exact_native_raw_attr_producers_refresh_validation_atomically(){let(mut d,mut f,mut p,owner,select)=validation_fixture();run(&mut d,&mut f,&mut p,r"var x=document.getElementById('select');x.setAttributeNS('urn:foreign','required','foreign');x.setAttributeNS(null,'REQUIRED','upper');if(x.required)throw 'exact required namespace';x.setAttributeNS(null,'required','A\ud800Z');var attr=x.getAttributeNodeNS(null,'required');if(!x.required||attr.value!=='A\ud800Z')throw 'native raw required presence';");assert!(f.controls[&select].required);assert!(f.validate_submission(&d,owner,None).is_err());run(&mut d,&mut f,&mut p,"attr.value='false';if(!x.required)throw 'presence not lexical value';x.removeAttributeNode(attr);if(x.required||attr.ownerElement!==null||attr.value!=='false')throw 'actual native Attr removal';");assert!(!f.controls[&select].required);assert!(f.validate_submission(&d,owner,None).is_ok());}
#[test]
fn select_required_writer_refusal_preserves_native_validation_and_recovers(){for mode in 0..4{let(mut d,mut f,mut p,owner,select)=validation_fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('select'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true});");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;let retained=p.state.retained;let limit=p.state.retained_limit;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=retained,_=>p.state.execution_deadline=Some(Instant::now())};assert!(p.runtime.execute("x.required=true;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).is_err());assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.dom_commits,p.state.retained),(commits,retained));assert!(!f.controls[&select].required);assert!(f.validate_submission(&d,owner,None).is_ok());p.state.retained_limit=limit;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"if(x.required||watch.takeRecords().length)throw 'required atomic refusal';x.required=true;if(watch.takeRecords().length!==1)throw 'required recovery';");assert!(f.controls[&select].required);assert!(f.validate_submission(&d,owner,None).is_err());}}
